module.exports = Object.assign(push, {
    options: ['--subdomain', '--passcode', '--user', '--client', '--mtls', '--to', '--async', '--sync'],
    flags: [],
    shortcuts: ['-s', '-p', '-u', '-c', '-m', '-2'],
    help: `
# SYNOPSIS

    *cds push* [ <extension-archive> | <extension-url> ]

    Push your extension to the SaaS app in order to enable or update it.

    The current working directory is used as the extension-project directory.

    You may alternatively specify a custom extension archive, either as a local
    file or as a URL to download it from.
    A download URL may contain Basic-Auth credentials as in
    'https://user:pass@host'.

    Unless a custom archive is given, the extension project will be
    automatically built in order to update the generated extension archive. This
    ensures the most recent extension model is pushed.

    Any authentication data will not be saved.


# OPTIONS

    *-2* | *--to* <url>

        Specify the URL of the extensible SaaS app. Determined from the current
        user's active
        CDS or Cloud Foundry login by default.

    *-s* | *--subdomain* <tenant-subdomain>

        The tenant subdomain. Determined from project settings by default.

    *-p* | *--passcode* <passcode>

        Tenant-specific passcode for authentication.

    *-u* | *--user* <name>[:[<password>]]

        Username and optionally password for authentication with Basic Auth in
        test scenarios.

    *-c* | *--client* [<clientid>[:<clientsecret>]]

        Client ID and optionally Client Secret for authentication. May also be
        provided via the CDS_LOGIN_CLIENT_ID and CDS_LOGIN_CLIENT_SECRET
        environment variables. See *cds login* for details.

    *-m* | *--mtls* [<clientid>]

        Client-certificate (mTLS) authentication. Client ID inline or via
        CDS_LOGIN_CLIENT_ID; certificate and key via CDS_LOGIN_CLIENT_CERT and
        CDS_LOGIN_CLIENT_KEY. See *cds login* for details.

    *--async*

        Use the asynchronous server API to upload extensions.


# SEE ALSO

    *cds pull* to get the CDS model of the SaaS app.

    *cds login* for more information on authentication options.

    *cds login* to save project settings and authentication data, simplifying
    multiple runs of this command.

`});


async function push([extArchive], options = {}) {
    const cds = require('../lib/index');
    await cds.plugins;

    const [username, password] = options.user?.split(':') ?? [];
    delete options.user;
    const { clientid, clientsecret, certificate, key } = options.mtls
        ? require('../lib/mtx/util/credentials').clientCertificate(options.mtls)
        : require('../lib/mtx/util/credentials').clientCredentials(options.client);
    delete options.client;
    delete options.mtls;

    const args = [{
        ...options,
        username,
        password,
        clientid,
        clientsecret,
        certificate,
        key
    }];
    if (extArchive) {
        args.push({ extArchive });
    }

    await require('../lib/mtx/push').run(...args);
}
